"""UI-only presentation of the frozen R4 model and complete illustrated guide."""
import json,html,re

def build(R,C,D,library):
 guide=json.loads((C/'manual/guide.json').read_text()); manifest=json.loads((C/'candidate-manifest.json').read_text())
 assert guide['steps'] and manifest['loading-all50']['parts']==946
 count=len(guide['steps']);rotatable=sum(bool(s.get('geometry_records')) for s in guide['steps'])
 # Retain only the operation data/script; rebuild its surface with this workbench.
 operation=(D/'index.html').read_text()
 css=(R/'viewer-workbench.css').read_text()
 js=library+'\n'+(R/'candidate-source-adapter.js').read_text()+'\n'+(R/'unified-reader-core.js').read_text()+'\n'+(R/'viewer-workbench.js').read_text()
 data={'imageRoot':'integrated/','guide':guide,'parts':manifest['loading-all50']['parts'],'model':(C/manifest['loading-all50']['file']).read_text(),'colors':(R/'candidate-colors.ldr').read_text()}
 safety='设计候选 · 未通过实体装配、承载与带电验收。按住外柄才能保持上位；无阻尼，谨防夹手与突然下落。'
 nav=lambda mode:'<header class="app-header"><div><span class="brand">Quadcuber</span> <span class="revision">最终结构 / 946件</span></div><nav class="primary-nav" aria-label="主导航"><a href="index.html"'+(' aria-current="page"'if mode=='whole'else'')+'>整机3D</a><a href="integrated-assembly.html"'+(' aria-current="page"'if mode=='assembly'else'')+'>逐步组装</a></nav></header><div class="safety-strip">'+safety+' <a href="#safety">风险与范围</a></div>'
 toolbar='''<div class="viewer-toolbar" aria-label="查看工具"><button type="button" data-view="iso">立体</button><button type="button" data-view="front">正视</button><button type="button" data-view="side">侧视</button><button type="button" data-view="top">俯视</button><button type="button" data-zoom="0.85" aria-label="放大模型">放大</button><button type="button" data-zoom="1.176470588" aria-label="缩小模型">缩小</button><button id="view-reset" type="button">复位</button><span class="spacer"></span><button id="view-fullscreen" type="button" aria-pressed="false">全屏查看</button><button id="image-fit" type="button" hidden>适合窗口</button><button id="image-actual" type="button" hidden>原图大小</button><a id="image-open" target="_blank" rel="noopener" hidden>打开原图</a><button id="model-retry" type="button" hidden>重试3D</button></div>'''
 viewport='''<div class="viewer-stage" id="viewer-stage" tabindex="0" aria-label="模型查看区"><div id="diagram-panel" class="diagram-panel fit" hidden><img id="step-image" alt=""></div><div id="model-status" class="model-status" role="status" aria-live="polite"></div></div>'''
 bom=re.search(r'<section class="panel" id="bom">([\s\S]*?)</section>',operation).group(1)
 aux='''<section class="aux"><details><summary>装卸动作演示</summary><p>查看放入、夹持交接、托座回落与退出的设计关系。只供审阅，不发送控制指令。</p><a href="integrated-operation.html">查看17阶段装卸动作</a></details><details id="bom"><summary>零件表与下载</summary><div class="downloads"><a href="integrated/manual.pdf" download>完整{count}页PDF</a><a href="integrated/full-revision.zip" download>模型与构建源文件（图解/PDF另下）</a><a href="integrated/models/loading-all50.mpd" download>946件整机MPD</a><a href="integrated/final-BOM.csv" download>整机BOM</a><a href="integrated/subsystem-BOM.csv" download>分组件BOM</a></div><div class="bom-wrap">'''+bom+'''</div></details><details id="safety"><summary>装配范围与未通过的验收</summary><p>本册共{count}步，含准备与检查：120件底盘从散件装配、150件支承与杠杆、四个机械臂组件的最终装配、接口与总装核对。四臂均从清单单件开始，全部946个实例逐步取用，没有预装核心；成品电机和舵机按采购件处理。</p><p>{rotatable}步提供精确记录对应的局部3D；其余步骤使用原始图解，包括准备与检查页。图解、3D与PDF使用同一最终结构数据。蓝色只表示本步新取件，合并步骤可能没有新件。</p><p>支承总成含20件重力回落杠杆。只有持续按住外柄才保持上位；夹头可靠接管后缓松回落40.8毫米。无阻尼，不保证实物自落、刚度或回落冲击安全。外柄对新桌面约33毫米、对新增梁约9毫米名义间隙，手只从末端三孔区域上方按压。</p><p>正常夹指开角不超过25°。实体装配路径、保持、载荷、手部隔离、自重回落与带电验收仍未通过；名义几何不代表实物验收。</p></details></section>'''
 aux=aux.replace('{count}',str(count)).replace('{rotatable}',str(rotatable))
 for mode,filename in [('whole','index.html'),('assembly','integrated-assembly.html')]:
  if mode=='whole':
   body=nav(mode)+'<main class="workspace"><section class="viewport-shell" id="viewport-shell">'+toolbar+viewport+'<div class="view-caption"><p><b>整机 · 946件</b> / 装料端姿</p><p>拖动旋转 · 滚轮 / 双指缩放 · R复位</p></div></section></main>'
  else:
   body=nav(mode)+'''<main class="workspace assembly"><section class="visual-column"><div class="reader-nav"><label class="sr-only" for="step-select">选择全册步骤</label><select id="step-select"></select><span id="step-progress" class="reader-progress" aria-live="polite"></span></div><section class="viewport-shell" id="viewport-shell"><div class="viewer-toolbar" aria-label="步骤视图"><button id="show-diagram" type="button" aria-pressed="true">本步图解</button><button id="show-model" type="button" aria-pressed="false">旋转本步3D</button><button id="highlight-toggle" type="button" aria-pressed="true">新增件高亮：开</button><span id="step-type"></span></div>'''+toolbar+viewport+'''<div class="view-caption"><p id="view-step-title"></p><p id="legend"><span class="legend-new">本步新件</span> <span class="legend-old">已有组件</span></p><p id="step-geometry-note"></p></div><div class="fullscreen-step-note"><details><summary>本步装配说明</summary><p id="expanded-parts"></p><ol id="expanded-instructions"></ol></details><p><b>停下核对：</b><span id="expanded-check"></span></p></div><div class="reader-bottom"><button id="step-prev" type="button">上一步</button><span id="step-progress-bottom" class="reader-progress"></span><button id="step-next" type="button">下一步</button></div></section></section><aside id="instruction-panel" class="instruction-panel" aria-label="本步装配说明"><label for="phase-select">装配章节</label><select id="phase-select" style="width:100%;margin:6px 0 12px"></select><div id="step-phase" class="phase-label"></div><h1 id="step-title"></h1><section class="parts-tray"><h2 style="margin-top:0">本步取件 / 组件</h2><p id="step-parts-summary"></p><ul id="step-parts"></ul></section><h2>装配方法</h2><ol id="step-instructions"></ol><section class="check-box"><h2 style="margin-top:0">停下核对</h2><p id="step-check"></p></section><p class="scope-note">左右方向键切换步骤。四臂均从单件开始；按本册顺序逐步搭建，成品电机和舵机内部不拆解。</p></aside></main>'''
  body+=aux+'<footer>最终结构 · 全机946件 / 底盘120 / 四臂676 / 支承150</footer>'
  payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
  result='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quadcuber · '+('整机3D'if mode=='whole'else str(count)+'步组装说明')+'</title><style>'+css+'</style></head><body data-mode="'+mode+'">'+body+'<script>window.WORKBENCH_DATA='+payload+';\n'+js+'</script></body></html>'
  (D/filename).write_text(result)

 from build_operation_workbench import build as build_operation
 build_operation(R,D,operation,nav('whole'),toolbar,aux,css)
